// Doorbell chime firmware for Arduino Uno
// D3: doorbell button (active LOW, internal pull-up)
// D5: chime output

const uint8_t BUTTON_PIN = 3;
const uint8_t CHIME_PIN  = 5;

// Timing constants (ms)
const unsigned long SAMPLE_INTERVAL   = 5;
const unsigned long DEBOUNCE_TIME     = 20;
const unsigned long MIN_PRESS_TIME    = 50;
const unsigned long RING_DURATION     = 2000;
const unsigned long HEARTBEAT_PERIOD  = 1000;
const unsigned long STUCK_TIMEOUT     = 10000;
const unsigned long STUCK_RELEASE     = 100;

// Debounce state
bool rawState = false;          // true = pressed (LOW)
bool debouncedState = false;    // true = pressed
bool lastRawState = false;
unsigned long lastSampleTime = 0;
unsigned long lastRawChangeTime = 0;

// Press tracking
bool pressCandidate = false;    // debounced pressed, waiting for 50 ms
unsigned long pressStartTime = 0;

// Ring state
bool ringInProgress = false;
unsigned long ringStartTime = 0;
bool ringArmed = true;          // must be released before next ring

// Stuck-button fault state
bool stuckFault = false;
unsigned long stuckStartTime = 0;
unsigned long stuckReleaseStart = 0;
bool stuckReleaseTracking = false;

// Heartbeat
unsigned long lastHeartbeat = 0;

void setup()
{
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(CHIME_PIN, OUTPUT);
  digitalWrite(CHIME_PIN, LOW);

  Serial.begin(9600);

  // Initialize debounce state from current reading
  rawState = (digitalRead(BUTTON_PIN) == LOW);
  lastRawState = rawState;
  debouncedState = rawState;
  lastRawChangeTime = millis();
  lastSampleTime = millis();
  lastHeartbeat = millis();
}

void loop()
{
  unsigned long now = millis();

  // Heartbeat (independent, non-blocking)
  if (now - lastHeartbeat >= HEARTBEAT_PERIOD)
  {
    lastHeartbeat += HEARTBEAT_PERIOD;
    Serial.println("alive");
  }

  // Sample button every 5 ms
  if (now - lastSampleTime >= SAMPLE_INTERVAL)
  {
    lastSampleTime += SAMPLE_INTERVAL;

    bool reading = (digitalRead(BUTTON_PIN) == LOW); // true = pressed

    if (reading != lastRawState)
    {
      lastRawState = reading;
      lastRawChangeTime = now;
    }

    // Accept new debounced state after 20 ms stable
    if ((now - lastRawChangeTime) >= DEBOUNCE_TIME && reading != debouncedState)
    {
      debouncedState = reading;
    }
  }

  // Stuck-button fault handling
  if (!stuckFault)
  {
    if (debouncedState)
    {
      // Track continuous press duration
      if (stuckStartTime == 0)
      {
        stuckStartTime = now;
      }
      if ((now - stuckStartTime) > STUCK_TIMEOUT)
      {
        stuckFault = true;
        digitalWrite(CHIME_PIN, LOW);
        ringInProgress = false;
        pressCandidate = false;
        stuckReleaseTracking = false;
      }
    }
    else
    {
      stuckStartTime = 0;
    }
  }
  else
  {
    // In fault: wait for release for 100 ms to clear
    if (!debouncedState)
    {
      if (!stuckReleaseTracking)
      {
        stuckReleaseTracking = true;
        stuckReleaseStart = now;
      }
      else if ((now - stuckReleaseStart) >= STUCK_RELEASE)
      {
        stuckFault = false;
        stuckReleaseTracking = false;
        stuckStartTime = 0;
        ringArmed = true;
      }
    }
    else
    {
      stuckReleaseTracking = false;
    }
  }

  // Ring completion
  if (ringInProgress)
  {
    if ((now - ringStartTime) >= RING_DURATION)
    {
      digitalWrite(CHIME_PIN, LOW);
      ringInProgress = false;
    }
  }

  // Button press logic (only when not in fault)
  if (!stuckFault)
  {
    if (ringInProgress)
    {
      // Ignore all button activity during ring; require release after
      ringArmed = false;
      pressCandidate = false;
    }
    else
    {
      if (debouncedState)
      {
        // Pressed: start candidate timer if not already
        if (!pressCandidate)
        {
          pressCandidate = true;
          pressStartTime = now;
        }
        else if (ringArmed && (now - pressStartTime) >= MIN_PRESS_TIME)
        {
          // Valid press confirmed: start ring
          digitalWrite(CHIME_PIN, HIGH);
          ringInProgress = true;
          ringStartTime = now;
          ringArmed = false;
          pressCandidate = false;
        }
      }
      else
      {
        // Released
        pressCandidate = false;
        if (!ringInProgress)
        {
          ringArmed = true;
        }
      }
    }
  }
}

