// Tank level controller for Arduino Uno
// A0: level sensor (10 mV/%), D6: pump relay

const uint8_t PIN_SENSOR = A0;
const uint8_t PIN_PUMP = 6;

const unsigned long SAMPLE_INTERVAL_MS = 50;
const unsigned long PRINT_INTERVAL_MS = 1000;

// Hysteresis thresholds (percent)
const float LEVEL_LOW_ON = 20.0;
const float LEVEL_HIGH_OFF = 80.0;

// Fault thresholds (percent)
const float FAULT_LOW = 2.0;
const float FAULT_HIGH = 98.0;

// Recovery: consecutive valid samples needed
const uint8_t RECOVERY_SAMPLES = 3;

// Filter: 3-sample average
const uint8_t FILTER_SIZE = 3;

float samples[FILTER_SIZE];
uint8_t sampleCount = 0;
uint8_t sampleIndex = 0;

float filteredLevel = 0.0;
bool haveValidReading = false;
bool faulty = false;
uint8_t recoveryCount = 0;

bool pumpOn = false;

unsigned long lastSampleMs = 0;
unsigned long lastPrintMs = 0;

// Read raw ADC and convert to percent
float readLevelPercent()
{
    int raw = analogRead(PIN_SENSOR);
    return raw * (5000.0 / 1023.0) / 10.0;
}

// Push a sample into the ring buffer and compute the average
float updateFilter(float value)
{
    samples[sampleIndex] = value;
    sampleIndex = (sampleIndex + 1) % FILTER_SIZE;
    if (sampleCount < FILTER_SIZE)
    {
        sampleCount++;
    }

    float sum = 0.0;
    for (uint8_t i = 0; i < sampleCount; i++)
    {
        sum += samples[i];
    }
    return sum / (float)sampleCount;
}

void setPump(bool on)
{
    pumpOn = on;
    digitalWrite(PIN_PUMP, on ? HIGH : LOW);
}

void setup()
{
    pinMode(PIN_PUMP, OUTPUT);
    digitalWrite(PIN_PUMP, LOW);
    pumpOn = false;

    Serial.begin(9600);

    // Seed filter buffer with first reading
    float first = readLevelPercent();
    for (uint8_t i = 0; i < FILTER_SIZE; i++)
    {
        samples[i] = first;
    }
    sampleCount = FILTER_SIZE;
    sampleIndex = 0;
    filteredLevel = first;

    lastSampleMs = millis();
    lastPrintMs = millis();
}

void loop()
{
    unsigned long now = millis();

    // Sample every 50 ms
    if (now - lastSampleMs >= SAMPLE_INTERVAL_MS)
    {
        lastSampleMs = now;

        float raw = readLevelPercent();
        filteredLevel = updateFilter(raw);

        bool outOfRange = (filteredLevel < FAULT_LOW) || (filteredLevel > FAULT_HIGH);

        if (outOfRange)
        {
            // Fault: pump OFF immediately, reset recovery
            if (!faulty)
            {
                faulty = true;
            }
            recoveryCount = 0;
            setPump(false);
        }
        else
        {
            if (faulty)
            {
                // Count consecutive valid samples for recovery
                if (recoveryCount < RECOVERY_SAMPLES)
                {
                    recoveryCount++;
                }
                if (recoveryCount >= RECOVERY_SAMPLES)
                {
                    faulty = false;
                    haveValidReading = true;
                }
                // Keep pump OFF while recovering
                setPump(false);
            }
            else
            {
                haveValidReading = true;

                // Normal hysteresis control
                if (filteredLevel <= LEVEL_LOW_ON)
                {
                    setPump(true);
                }
                else if (filteredLevel >= LEVEL_HIGH_OFF)
                {
                    setPump(false);
                }
                // else hold current state
            }
        }
    }

    // Print every 1000 ms
    if (now - lastPrintMs >= PRINT_INTERVAL_MS)
    {
        lastPrintMs = now;

        Serial.print("Level: ");
        Serial.print(filteredLevel, 1);
        Serial.println(" %");
    }
}

// Button-controlled light with debounce and 4 s non-blocking timer
// D2: button input (active LOW, internal pull-up)
// D7: light output

const uint8_t BUTTON_PIN = 2;
const uint8_t LIGHT_PIN  = 7;

const unsigned long DEBOUNCE_MS = 20;
const unsigned long ON_TIME_MS  = 4000;

// Debounce state
int lastRawReading = HIGH;          // last raw sample of the pin
int stableState    = HIGH;          // debounced state (HIGH = released)
unsigned long lastChangeMs = 0;     // when the raw reading last changed

// Light timer state
bool lightOn = false;
unsigned long lightStartMs = 0;

void setup()
{
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LIGHT_PIN, OUTPUT);
  digitalWrite(LIGHT_PIN, LOW);

  lastRawReading = digitalRead(BUTTON_PIN);
  stableState    = lastRawReading;
  lastChangeMs   = millis();
}

void loop()
{
  unsigned long now = millis();

  // --- Debounce ---
  int raw = digitalRead(BUTTON_PIN);
  if (raw != lastRawReading)
  {
    lastRawReading = raw;
    lastChangeMs = now;
  }

  if ((now - lastChangeMs) >= DEBOUNCE_MS && raw != stableState)
  {
    stableState = raw;
    // Accepted press = stable LOW transition
    if (stableState == LOW)
    {
      digitalWrite(LIGHT_PIN, HIGH);
      lightOn = true;
      lightStartMs = now;
    }
  }

  // --- Non-blocking on-timer ---
  if (lightOn && (now - lightStartMs) >= ON_TIME_MS)
  {
    digitalWrite(LIGHT_PIN, LOW);
    lightOn = false;
  }
}

// Button-controlled light with debounce and 4 s non-blocking timer
// D2: button input (active LOW, internal pull-up)
// D7: light output

const uint8_t BUTTON_PIN = 2;
const uint8_t LIGHT_PIN  = 7;

const unsigned long DEBOUNCE_MS = 20;
const unsigned long ON_TIME_MS  = 4000;

// Debounce state
int lastRawReading = HIGH;          // last raw sample of the pin
int stableState    = HIGH;          // debounced state (HIGH = released)
