void setup()
{
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LIGHT_PIN, OUTPUT);
  digitalWrite(LIGHT_PIN, LOW);

  // Start from the released state so a button held LOW at power-on
  // is debounced and accepted as a press, not absorbed as the initial state.
  lastRawReading = HIGH;
  stableState    = HIGH;
  lastChangeMs   = millis();
}

void loop()
{
  unsigned long now = millis();

  // --- Debounce ---
  int raw = digitalRead(BUTTON_PIN);
  if (raw != lastRawReading)
  {
    lastRawReading = raw;
    lastChangeMs = now;
  }

  if ((now - lastChangeMs) >= DEBOUNCE_MS && raw != stableState)
  {
    stableState = raw;
    // Accepted press = stable LOW transition
    if (stableState == LOW)
    {
      digitalWrite(LIGHT_PIN, HIGH);
      lightOn = true;
      lightStartMs = now;
    }
  }

  // --- Non-blocking on-timer ---
  if (lightOn && (now - lightStartMs) >= ON_TIME_MS)
  {
    digitalWrite(LIGHT_PIN, LOW);
    lightOn = false;
  }
}

// Doorbell chime firmware for Arduino Uno
// D3: active-low push button with internal pull-up
// D5: chime output

const uint8_t BUTTON_PIN = 3;
const uint8_t CHIME_PIN  = 5;

const unsigned long DEBOUNCE_MS   = 10;
const unsigned long MIN_PRESS_MS  = 50;
const unsigned long RING_MS       = 2000;
const unsigned long HEARTBEAT_MS  = 1000;

// Debounce state
bool rawLast        = true;   // last raw reading (true = high/released)
bool debouncedState = true;   // debounced state (true = high/released)
unsigned long rawChangeTime = 0;

// Press tracking
bool pressCandidate   = false; // debounced low, waiting to confirm 50 ms
unsigned long pressStartTime = 0;

// Ring state
bool ringing        = false;
unsigned long ringStartTime = 0;
bool armed          = true;   // must be released before next ring

// Heartbeat
unsigned long lastHeartbeat = 0;

void setup()
{
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(CHIME_PIN, OUTPUT);
  digitalWrite(CHIME_PIN, LOW);

  Serial.begin(9600);

  // Initialize debounce state from current reading
  rawLast = (digitalRead(BUTTON_PIN) == HIGH);
  debouncedState = rawLast;
  rawChangeTime = millis();

  lastHeartbeat = millis();
}

void loop()
{
  unsigned long now = millis();

  // --- Debounce filter ---
  bool raw = (digitalRead(BUTTON_PIN) == HIGH);
  if (raw != rawLast)
  {
    rawLast = raw;
    rawChangeTime = now;
  }
  if ((now - rawChangeTime) >= DEBOUNCE_MS && debouncedState != rawLast)
  {
    debouncedState = rawLast;
  }

  // --- Ring timing ---
  if (ringing)
  {
    if ((now - ringStartTime) >= RING_MS)
    {
      digitalWrite(CHIME_PIN, LOW);
      ringing = false;
    }
  }

  // --- Button logic (ignored while ringing) ---
  if (!ringing)
  {
    if (debouncedState == false)
    {
      // Debounced low
      if (!pressCandidate)
      {
        pressCandidate = true;
        pressStartTime = now;
      }
      else if (armed && (now - pressStartTime) >= MIN_PRESS_MS)
      {
        // Valid press confirmed
        digitalWrite(CHIME_PIN, HIGH);
        ringing = true;
        ringStartTime = now;
        armed = false;
        pressCandidate = false;
      }
    }
    else
    {
      // Debounced high: release
      pressCandidate = false;
      armed = true;
    }
  }

  // --- Heartbeat ---
  if ((now - lastHeartbeat) >= HEARTBEAT_MS)
  {
    lastHeartbeat += HEARTBEAT_MS;
    // Guard against drift if loop was delayed a lot
    if ((now - lastHeartbeat) >= HEARTBEAT_MS)
    {
      lastHeartbeat = now;
    }
    Serial.println("alive");
  }
}

