// Tank level controller for Arduino Uno
// A0: level sensor (10 mV/%), D6: pump relay

const uint8_t PIN_SENSOR = A0;
const uint8_t PIN_PUMP   = 6;

const unsigned long SAMPLE_INTERVAL_MS = 100;
const unsigned long PRINT_INTERVAL_MS  = 1000;
const unsigned long DEBOUNCE_MS        = 500;

// Fault thresholds
const float FAULT_LOW  = 2.0;
const float FAULT_HIGH = 98.0;
const uint8_t FAULT_RECOVER_SAMPLES = 3;

// Control hysteresis
const float PUMP_ON_LEVEL  = 20.0;
const float PUMP_OFF_LEVEL = 80.0;

// Filter: average of last 3 samples
float samples[3] = {0.0, 0.0, 0.0};
uint8_t sampleIdx = 0;
uint8_t sampleCount = 0;
float filteredLevel = 0.0;

bool pumpOn = false;
bool sensorFaulty = false;
uint8_t recoveryCount = 0;

unsigned long lastSampleMs = 0;
unsigned long lastPrintMs  = 0;
unsigned long lastPumpChangeMs = 0;
bool pumpChangePending = false;
bool pendingPumpState = false;

void setup()
{
  pinMode(PIN_PUMP, OUTPUT);
  digitalWrite(PIN_PUMP, LOW);
  Serial.begin(9600);

  // Take an immediate reading so startup evaluates level right away
  takeSample();
  evaluateControl();
  lastSampleMs = millis();
  lastPrintMs  = millis();
}

void loop()
{
  unsigned long now = millis();

  if (now - lastSampleMs >= SAMPLE_INTERVAL_MS)
  {
    lastSampleMs = now;
    takeSample();
    evaluateControl();
  }

  // Commit debounced pump change once stable for DEBOUNCE_MS
  if (pumpChangePending && (now - lastPumpChangeMs >= DEBOUNCE_MS))
  {
    pumpOn = pendingPumpState;
    digitalWrite(PIN_PUMP, pumpOn ? HIGH : LOW);
    pumpChangePending = false;
  }

  if (now - lastPrintMs >= PRINT_INTERVAL_MS)
  {
    lastPrintMs = now;
    printLevel();
  }
}

void takeSample()
{
  int raw = analogRead(PIN_SENSOR);
  float level = raw * (5000.0 / 1023.0) / 10.0;

  samples[sampleIdx] = level;
  sampleIdx = (sampleIdx + 1) % 3;
  if (sampleCount < 3)
  {
    sampleCount++;
  }

  float sum = 0.0;
  for (uint8_t i = 0; i < sampleCount; i++)
  {
    sum += samples[i];
  }
  filteredLevel = sum / (float)sampleCount;
}

void evaluateControl()
{
  // Fault detection
  if (filteredLevel < FAULT_LOW || filteredLevel > FAULT_HIGH)
  {
    sensorFaulty = true;
    recoveryCount = 0;
    requestPumpState(false);
    return;
  }

  if (sensorFaulty)
  {
    // Require 3 consecutive valid samples to clear fault
    recoveryCount++;
    if (recoveryCount >= FAULT_RECOVER_SAMPLES)
    {
      sensorFaulty = false;
      recoveryCount = 0;
    }
    else
    {
      requestPumpState(false);
      return;
    }
  }

  // Normal hysteresis control
  if (!pumpOn && filteredLevel <= PUMP_ON_LEVEL)
  {
    requestPumpState(true);
  }
  else if (pumpOn && filteredLevel >= PUMP_OFF_LEVEL)
  {
    requestPumpState(false);
  }
}

void requestPumpState(bool desired)
{
  if (desired == pumpOn && !pumpChangePending)
  {
    return;
  }
  if (pumpChangePending && desired == pendingPumpState)
  {
    return;
  }
  // Start (or restart) debounce window
  pendingPumpState = desired;
  pumpChangePending = true;
  lastPumpChangeMs = millis();
}

void printLevel()
{
  Serial.print(F("Level: "));
  Serial.print(filteredLevel, 1);
  Serial.println(F(" %"));
}

