// Doorbell firmware for Arduino Uno
// D3: button input (active LOW, internal pull-up)
// D5: chime output

const uint8_t BUTTON_PIN = 3;
const uint8_t CHIME_PIN  = 5;

const unsigned long DEBOUNCE_MS   = 10;
const unsigned long RING_MS       = 2000;
const unsigned long HEARTBEAT_MS  = 1000;

// Debounce state
bool rawLast        = HIGH;   // last raw reading
bool stableState    = HIGH;   // debounced state
unsigned long lastRawChange = 0;

// Ring state
bool ringActive     = false;
unsigned long ringStart = 0;

// Heartbeat state
unsigned long lastHeartbeat = 0;

void setup()
{
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(CHIME_PIN, OUTPUT);
  digitalWrite(CHIME_PIN, LOW);

  Serial.begin(9600);

  rawLast     = digitalRead(BUTTON_PIN);
  stableState = rawLast;
  lastRawChange = millis();
  lastHeartbeat = millis();
}

void loop()
{
  unsigned long now = millis();

  // --- Debounce ---
  bool raw = digitalRead(BUTTON_PIN);
  if (raw != rawLast)
  {
    rawLast = raw;
    lastRawChange = now;
  }

  // Accept a new stable state only after it has been held for DEBOUNCE_MS
  if ((now - lastRawChange) >= DEBOUNCE_MS && raw != stableState)
  {
    stableState = raw;

    // Falling edge (HIGH -> LOW) = accepted press
    if (stableState == LOW)
    {
      if (!ringActive)
      {
        digitalWrite(CHIME_PIN, HIGH);
        ringActive = true;
        ringStart  = now;
      }
      // else: ignore presses during a ring
    }
  }

  // --- Ring timing ---
  if (ringActive && (now - ringStart) >= RING_MS)
  {
    digitalWrite(CHIME_PIN, LOW);
    ringActive = false;
  }

  // --- Heartbeat ---
  if ((now - lastHeartbeat) >= HEARTBEAT_MS)
  {
    lastHeartbeat += HEARTBEAT_MS;
    // Guard against drift if loop was delayed
    if ((now - lastHeartbeat) >= HEARTBEAT_MS)
    {
      lastHeartbeat = now;
    }
    Serial.println("alive");
  }
}

// Tank level pump controller for Arduino Uno
// Reads A0 (10 mV/%), controls pump relay on D6 with hysteresis and fault handling.

const uint8_t PIN_SENSOR = A0;
const uint8_t PIN_PUMP = 6;

const unsigned long SAMPLE_INTERVAL_MS = 100;
const unsigned long PRINT_INTERVAL_MS = 1000;

const float LOW_ON_PCT = 20.0;
const float HIGH_OFF_PCT = 80.0;
const float FAULT_LOW_PCT = 2.0;
const float FAULT_HIGH_PCT = 98.0;

// Median-of-3 sample buffer
float samples[3];
uint8_t sampleCount = 0;
uint8_t sampleIndex = 0;

bool pumpOn = false;
bool faultActive = false;
bool haveValidReading = false;
float lastValidLevel = 0.0;
float lastReportedLevel = 0.0;

unsigned long lastSampleMs = 0;
unsigned long lastPrintMs = 0;

// Convert raw ADC to percent using 10 mV/% scale
float rawToPercent(int raw)
{
  float mv = (float)raw * 5000.0 / 1023.0;
  return mv / 10.0;
}

// Median of up to 3 samples
float medianOfSamples()
{
  if (sampleCount == 0)
  {
    return 0.0;
  }
  if (sampleCount == 1)
  {
    return samples[0];
  }
  if (sampleCount == 2)
  {
    return (samples[0] + samples[1]) * 0.5;
  }
  float a = samples[0];
  float b = samples[1];
  float c = samples[2];
  float lo = a;
  float hi = a;
  if (b < lo) lo = b;
  if (b > hi) hi = b;
  if (c < lo) lo = c;
  if (c > hi) hi = c;
  return (a + b + c) - lo - hi;
}

void setPump(bool on)
{
  pumpOn = on;
  digitalWrite(PIN_PUMP, on ? HIGH : LOW);
}

void setup()
{
  pinMode(PIN_PUMP, OUTPUT);
  digitalWrite(PIN_PUMP, LOW);
  pumpOn = false;
  Serial.begin(9600);
  lastSampleMs = millis();
  lastPrintMs = millis();
}

void loop()
{
  unsigned long now = millis();

  // Sample every 100 ms
  if (now - lastSampleMs >= SAMPLE_INTERVAL_MS)
  {
    lastSampleMs = now;

    int raw = analogRead(PIN_SENSOR);
    float level = rawToPercent(raw);

    samples[sampleIndex] = level;
    sampleIndex = (sampleIndex + 1) % 3;
    if (sampleCount < 3)
    {
      sampleCount++;
    }

    float filtered = medianOfSamples();

    // Fault detection on filtered value
    if (filtered < FAULT_LOW_PCT || filtered > FAULT_HIGH_PCT)
    {
      faultActive = true;
      setPump(false);
    }
    else
    {
      // Valid range
      if (faultActive)
      {
        // Exit fault: resume with pump OFF
        faultActive = false;
        setPump(false);
      }

      haveValidReading = true;
      lastValidLevel = filtered;

      if (!faultActive)
      {
        if (filtered <= LOW_ON_PCT)
        {
          setPump(true);
        }
        else if (filtered >= HIGH_OFF_PCT)
        {
          setPump(false);
        }
        // else keep current state
      }
    }

    // Track reported level
    if (faultActive)
    {
      lastReportedLevel = haveValidReading ? lastValidLevel : 0.0;
    }
    else
    {
      lastReportedLevel = filtered;
    }
  }

  // Print every 1000 ms
  if (now - lastPrintMs >= PRINT_INTERVAL_MS)
  {
    lastPrintMs = now;
    Serial.print("Level: ");
    Serial.print(lastReportedLevel, 1);
    Serial.println(" %");
  }
}

// Tank level pump controller for Arduino Uno
// Reads A0 (10 mV/%), controls pump relay on D6 with hysteresis and fault handling.

const uint8_t PIN_SENSOR = A0;
const uint8_t PIN_PUMP = 6;

const unsigned long SAMPLE_INTERVAL_MS = 100;
const unsigned long PRINT_INTERVAL_MS = 1000;

const float LOW_ON_PCT = 20.0;
const float HIGH_OFF_PCT = 80.0;
const float FAULT_LOW_PCT = 2.0;
const float FAULT_HIGH_PCT = 98.0;

// Median-of-3 sample buffer
float samples[3];
uint8_t sampleCount = 0;
uint8_t sampleIndex = 0;

bool pumpOn = false;
bool faultActive = false;
bool haveValidReading = false;
float lastValidLevel = 0.0;
float lastReportedLevel = 0.0;

unsigned long lastSampleMs = 0;
unsigned long lastPrintMs = 0;

// Convert raw ADC to percent using 10 mV/% scale
float rawToPercent(int raw)
{
  float mv = (float)raw * 5000.0 / 1023.0;
  return mv / 10.0;
}

// Median of up to 3 samples
float medianOfSamples()
{
  if (sampleCount == 0)
  {
    return 0.0;
  }
  if (sampleCount == 1)
  {
    return samples[0];
  }
  if (sampleCount == 2)
  {
    return (samples[0] + samples[1]) * 0.5;
  }
  float a = samples[0];
  float b = samples[1];
  float c = samples[2];
  float lo = a;
  float hi = a;
  if (b < lo) lo = b;
  if (b > hi) hi = b;
  if (c < lo) lo = c;
  if (c > hi) hi = c;
  return (a + b + c) - lo - hi;
}

void setPump(bool on)
{
  pumpOn = on;
  digitalWrite(PIN_PUMP, on ? HIGH : LOW);
}

void setup()
{
  pinMode(PIN_PUMP, OUTPUT);
  digitalWrite(PIN_PUMP, LOW);
  pumpOn = false;
  Serial.begin(9600);
  lastSampleMs = millis();
  lastPrintMs = millis();
}

void loop()
{
  unsigned long now = millis();

  // Sample every 100 ms
  if (now - lastSampleMs >= SAMPLE_INTERVAL_MS)
  {
    lastSampleMs = now;

    int raw = analogRead(PIN_SENSOR);
    float level = rawToPercent(raw);

    samples[sampleIndex] = level;
    sampleIndex = (sampleIndex + 1) % 3;
    if (sampleCount < 3)
    {
      sampleCount++;
    }

    float filtered = medianOfSamples();

    // Fault detection on filtered value
    if (filtered < FAULT_LOW_PCT || filtered > FAULT_HIGH_PCT)
    {
      faultActive = true;
      setPump(false);
    }
    else
    {
      // Valid range
      if (faultActive)
      {
        // Exit fault: resume with pump OFF
        faultActive = false;
        setPump(false);
      }

      haveValidReading = true;
      lastValidLevel = filtered;

      if (!faultActive)
      {
        if (filtered <= LOW_ON_PCT)
        {
          setPump(true);
        }
        else if (filtered >= HIGH_OFF_PCT)
        {
          setPump(false);
        }
        // else keep current state
      }
    }

    // Track reported level: always report the measured level
    lastReportedLevel = filtered;
  }

  // Print every 1000 ms
  if (now - lastPrintMs >= PRINT_INTERVAL_MS)
  {
    lastPrintMs = now;
    Serial.print("Level: ");
    Serial.print(lastReportedLevel, 1);
    Serial.println(" %");
  }
}

// Button on D2 (active low, internal pull-up), light on D7.
// Debounced press turns light on for 4 s; presses while on restart timer.

const uint8_t BUTTON_PIN = 2;
const uint8_t LIGHT_PIN  = 7;

const unsigned long DEBOUNCE_MS = 20;
const unsigned long LIGHT_MS    = 4000;

bool rawLevel;          // current raw reading (true = HIGH / released)
bool stableLevel;       // debounced level (true = HIGH / released)
unsigned long lastChangeMs = 0;

bool lightOn = false;
unsigned long lightStartMs = 0;

void setup()
{
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LIGHT_PIN, OUTPUT);
  digitalWrite(LIGHT_PIN, LOW);

  rawLevel = (digitalRead(BUTTON_PIN) == HIGH);
  stableLevel = rawLevel;
  lastChangeMs = millis();
}

void loop()
{
  unsigned long now = millis();

  // Debounce: track raw changes, accept after stable for DEBOUNCE_MS.
  bool reading = (digitalRead(BUTTON_PIN) == HIGH);
  if (reading != rawLevel)
  {
    rawLevel = reading;
    lastChangeMs = now;
  }

  if (rawLevel != stableLevel && (now - lastChangeMs) >= DEBOUNCE_MS)
  {
    bool previous = stableLevel;
    stableLevel = rawLevel;

    // Valid press = HIGH-to-LOW transition after debounce.
    if (previous && !stableLevel)
    {
      digitalWrite(LIGHT_PIN, HIGH);
      lightOn = true;
      lightStartMs = now;
    }
  }

  // Turn light off when the 4 s timer expires.
  if (lightOn && (now - lightStartMs) >= LIGHT_MS)
  {
    digitalWrite(LIGHT_PIN, LOW);
    lightOn = false;
  }
}

