// Panic alarm
// Button on D2 to ground, siren on D8, heartbeat printed over serial.
const int BUTTON_PIN = 2;
const int SIREN_PIN = 8;

const unsigned long HB_INTERVAL = 500;
const unsigned long SIREN_TIME = 3000;
const unsigned long PRESS_CONFIRM = 40;

unsigned long lastHb = 0;
unsigned long pressStart = 0;
bool pressActive = false;
bool sirenOn = false;
unsigned long sirenStart = 0;

void setup()
{
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    pinMode(SIREN_PIN, OUTPUT);
    Serial.begin(9600);
}

void loop()
{
    unsigned long now = millis();

    // Heartbeat every 500 ms, always.
    if (now - lastHb >= HB_INTERVAL)
    {
        lastHb = now;
        Serial.println("hb");
    }

    // End the siren after 3 seconds.
    if (sirenOn && (now - sirenStart >= SIREN_TIME))
    {
        sirenOn = false;
        digitalWrite(SIREN_PIN, LOW);
    }

    // Confirm a press only if the button stays LOW continuously.
    if (!sirenOn)
    {
        if (digitalRead(BUTTON_PIN) == LOW)
        {
            if (!pressActive)
            {
                pressActive = true;
                pressStart = now;
            }
            else if (now - pressStart >= PRESS_CONFIRM)
            {
                pressActive = false;
                sirenOn = true;
                sirenStart = now;
                digitalWrite(SIREN_PIN, HIGH);
            }
        }
        else
        {
            pressActive = false;
        }
    }
    else
    {
        pressActive = false;
    }
}

