// Thermostat fan controller
// LM35 temperature sensor on A0, fan driver on D9.
const int SENSOR_PIN = A0;
const int FAN_PIN = 9;
const float FAN_ON_C = 30.0;
const float FAN_OFF_C = 27.0;
const float FAULT_LOW_C = 2.0;
const float FAULT_HIGH_C = 120.0;
const unsigned long CONFIRM_MS = 400;
const unsigned long FAULT_CONFIRM_MS = 800;

bool fanOn = false;
bool pendingValid = false;
bool pendingState = false;
unsigned long pendingSince = 0;

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    Serial.begin(9600);
}

void loop()
{
    int raw = analogRead(SENSOR_PIN);
    float tempC = raw * (5.0 / 1023.0) * 100.0;

    bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);

    bool desired;
    unsigned long confirmMs;
    if (fault)
    {
        desired = true;
        confirmMs = FAULT_CONFIRM_MS;
    }
    else if (fanOn)
    {
        desired = (tempC > FAN_OFF_C);
        confirmMs = CONFIRM_MS;
    }
    else
    {
        desired = (tempC >= FAN_ON_C);
        confirmMs = CONFIRM_MS;
    }

    if (desired == fanOn)
    {
        pendingValid = false;
    }
    else
    {
        if (!pendingValid || pendingState != desired)
        {
            pendingValid = true;
            pendingState = desired;
            pendingSince = millis();
        }
        if (millis() - pendingSince >= confirmMs)
        {
            fanOn = desired;
            pendingValid = false;
        }
    }

    digitalWrite(FAN_PIN, fanOn ? HIGH : LOW);

    Serial.print("temp=");
    Serial.println(tempC);
    delay(100);
}

