// Panic alarm
// Button on D2 to ground, siren on D8, heartbeat printed over serial.
const int BUTTON_PIN = 2;
const int SIREN_PIN = 8;

const unsigned long HEARTBEAT_MS = 500;
const unsigned long SIREN_MS = 3000;
const unsigned long DEBOUNCE_MS = 50;

unsigned long lastHeartbeat = 0;
unsigned long pressStart = 0;
bool pressPending = false;
bool sirenOn = false;
unsigned long sirenStart = 0;

void setup()
{
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    pinMode(SIREN_PIN, OUTPUT);
    Serial.begin(9600);
}

void loop()
{
    unsigned long now = millis();

    // Heartbeat
    if (now - lastHeartbeat >= HEARTBEAT_MS)
    {
        lastHeartbeat = now;
        Serial.println("hb");
    }

    // Siren timing
    if (sirenOn && (now - sirenStart >= SIREN_MS))
    {
        sirenOn = false;
        digitalWrite(SIREN_PIN, LOW);
    }

    // Button debounce
    bool pressed = (digitalRead(BUTTON_PIN) == LOW);
    if (pressed)
    {
        if (!pressPending)
        {
            pressPending = true;
            pressStart = now;
        }
        else if (!sirenOn && (now - pressStart >= DEBOUNCE_MS))
        {
            pressPending = false;
            sirenOn = true;
            sirenStart = now;
            digitalWrite(SIREN_PIN, HIGH);
        }
    }
    else
    {
        pressPending = false;
    }
}

