// Push button toggles an LED
// Button on D2 to ground, using the internal pull-up. LED on D13.
const int BUTTON_PIN = 2;
const int LED_PIN = 13;

// Debounce: require the new state to hold for several consecutive samples.
// Loop period is ~1 ms, so 30 samples ~= 30 ms, longer than the 20 ms bounce
// yet well within the 100 ms response deadline.
const int DEBOUNCE_SAMPLES = 30;

int lastState = HIGH;
int stableState = HIGH;
int sampleCount = 0;
bool ledOn = false;

void setup()
{
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    pinMode(LED_PIN, OUTPUT);
}

void loop()
{
    int state = digitalRead(BUTTON_PIN);

    if (state == lastState)
    {
        if (sampleCount < DEBOUNCE_SAMPLES)
        {
            sampleCount++;
        }
    }
    else
    {
        lastState = state;
        sampleCount = 0;
    }

    if (sampleCount >= DEBOUNCE_SAMPLES && stableState != lastState)
    {
        stableState = lastState;

        if (stableState == LOW)
        {
            ledOn = !ledOn;
            digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
        }
    }
}

