// Button on D2 to ground, using the internal pull-up. LED on D13.
const int BUTTON_PIN = 2;
const int LED_PIN = 13;

// Debounce: require the raw reading to hold for several consecutive samples.
// Loop period is well under 1 ms, so 8 samples reject the 20 ms bounce while
// still accepting a press far inside the 100 ms deadline.
const int DEBOUNCE_SAMPLES = 8;

int lastState = HIGH;
int stableState = HIGH;
int sampleCount = 0;
bool ledOn = false;

void setup()
{
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    pinMode(LED_PIN, OUTPUT);
}

void loop()
{
    int state = digitalRead(BUTTON_PIN);

    if (state == lastState)
    {
        if (sampleCount < DEBOUNCE_SAMPLES)
        {
            sampleCount++;
        }
    }
    else
    {
        lastState = state;
        sampleCount = 0;
    }

    if (sampleCount >= DEBOUNCE_SAMPLES && stableState != lastState)
    {
        stableState = lastState;

        if (stableState == LOW)
        {
            ledOn = !ledOn;
            digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
        }
    }
}

