int onCount = 0;
int offCount = 0;
int faultCount = 0;
unsigned long lastSwitchMs = 0;

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    Serial.begin(9600);
}

void loop()
{
    int raw = analogRead(SENSOR_PIN);
    float tempC = raw * (5.0 / 1023.0) * 100.0;

    bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);
    unsigned long now = millis();

    if (fault)
    {
        if (faultCount < CONFIRM_SAMPLES)
        {
            faultCount++;
        }
        onCount = 0;
        offCount = 0;
        if (faultCount >= CONFIRM_SAMPLES && !fanOn)
        {
            // Fail-safe: never held back by the dwell limiter.
            fanOn = true;
            lastSwitchMs = now;
        }
    }
    else
    {
        faultCount = 0;

        if (!fanOn)
        {
            if (tempC >= FAN_ON_C)
            {
                if (onCount < CONFIRM_SAMPLES)
                {
                    onCount++;
                }
                if (onCount >= CONFIRM_SAMPLES && (now - lastSwitchMs) >= MIN_DWELL_MS)
                {
                    fanOn = true;
                    lastSwitchMs = now;
                    onCount = 0;
                    offCount = 0;
                }
            }
            else
            {
                onCount = 0;
            }
        }
        else
        {
            if (tempC <= FAN_OFF_C)
            {
                if (offCount < CONFIRM_SAMPLES)
                {
                    offCount++;
                }
                if (offCount >= CONFIRM_SAMPLES && (now - lastSwitchMs) >= MIN_DWELL_MS)
                {
                    fanOn = false;
                    lastSwitchMs = now;
                    onCount = 0;
                    offCount = 0;
                }
            }
            else
            {
                offCount = 0;
            }
        }
    }

    digitalWrite(FAN_PIN, fanOn ? HIGH : LOW);

    Serial.print("temp=");
    Serial.println(tempC);
