// LM35 temperature sensor on A0, fan driver on D9.
const int SENSOR_PIN = A0;
const int FAN_PIN = 9;
const float FAN_ON_C = 30.0;
const float FAN_OFF_C = 27.0;
const float FAULT_LOW_C = 2.0;
const float FAULT_HIGH_C = 120.0;
const int CONFIRM_SAMPLES = 3;
const unsigned long TOGGLE_WINDOW_MS = 5000UL;
const int MAX_TOGGLES = 2;

bool fanOn = false;
bool pendingState = false;
int pendingCount = 0;

unsigned long toggleTimes[MAX_TOGGLES];
int toggleCount = 0;

bool canToggle(unsigned long now)
{
    // Count toggles still inside the window.
    int inWindow = 0;
    for (int i = 0; i < toggleCount; i++)
    {
        if (now - toggleTimes[i] < TOGGLE_WINDOW_MS)
        {
            inWindow++;
        }
    }
    return inWindow < MAX_TOGGLES;
}

void recordToggle(unsigned long now)
{
    if (toggleCount < MAX_TOGGLES)
    {
        toggleTimes[toggleCount] = now;
        toggleCount++;
    }
    else
    {
        // Shift out the oldest and append the newest.
        for (int i = 1; i < MAX_TOGGLES; i++)
        {
            toggleTimes[i - 1] = toggleTimes[i];
        }
        toggleTimes[MAX_TOGGLES - 1] = now;
    }
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    Serial.begin(9600);
}

void loop()
{
    unsigned long now = millis();

    int raw = analogRead(SENSOR_PIN);
    float tempC = raw * (5.0 / 1023.0) * 100.0;

    bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);

    bool desired;
    if (fault)
    {
        desired = true;
    }
    else if (tempC >= FAN_ON_C)
    {
        desired = true;
    }
    else if (tempC <= FAN_OFF_C)
    {
        desired = false;
    }
    else
    {
        desired = fanOn;
    }

    if (desired == fanOn)
    {
        pendingCount = 0;
    }
    else
    {
        if (desired == pendingState)
        {
            pendingCount++;
        }
        else
        {
            pendingState = desired;
            pendingCount = 1;
        }

        if (pendingCount >= CONFIRM_SAMPLES)
        {
            // Fail-safe (fault) bypasses the toggle limiter.
            if (fault || canToggle(now))
            {
                fanOn = desired;
                recordToggle(now);
                pendingCount = 0;
            }
        }
    }

    digitalWrite(FAN_PIN, fanOn ? HIGH : LOW);

    Serial.print("temp=");
    Serial.println(tempC);
    delay(100);
}

