{
    pinMode(FAN_PIN, OUTPUT);
    Serial.begin(9600);
}

void loop()
{
    int raw = analogRead(SENSOR_PIN);
    float tempC = raw * (5.0 / 1023.0) * 100.0;

    bool fault = (tempC < FAULT_LOW_C || tempC > FAULT_HIGH_C);

    bool wantOn;
    if (fault)
    {
        wantOn = true;
    }
    else if (tempC >= FAN_ON_C)
    {
        wantOn = true;
    }
    else if (tempC <= FAN_OFF_C)
    {
        wantOn = false;
    }
    else
    {
        wantOn = fanOn;
    }

    if (wantOn == fanOn)
    {
        pendingCount = 0;
    }
    else
    {
        if (wantOn == pendingState)
        {
            pendingCount++;
        }
        else
        {
            pendingState = wantOn;
            pendingCount = 1;
        }

        bool confirmed = (pendingCount >= CONFIRM_SAMPLES);
        bool dwellOk = (millis() - lastSwitchMs >= MIN_DWELL_MS);

        // Fail-safe ON must never be held back by the dwell limiter.
        if (confirmed && (dwellOk || (wantOn && fault)))
        {
            fanOn = wantOn;
            pendingCount = 0;
            lastSwitchMs = millis();
        }
    }

    digitalWrite(FAN_PIN, fanOn ? HIGH : LOW);

    Serial.print("temp=");
    Serial.println(tempC);
    delay(100);
}

// Thermostat fan controller
// LM35 temperature sensor on A0, fan driver on D9.
const int SENSOR_PIN = A0;
const int FAN_PIN = 9;
const float FAN_ON_C = 30.0;
const float FAN_OFF_C = 27.0;
const float FAULT_LOW_C = 2.0;
const float FAULT_HIGH_C = 120.0;
const int CONFIRM_SAMPLES = 3;
const unsigned long TOGGLE_WINDOW_MS = 5000UL;
const int MAX_TOGGLES = 2;

bool fanOn = false;
bool pendingState = false;
int pendingCount = 0;

unsigned long toggleTimes[MAX_TOGGLES];
int toggleCount = 0;

bool toggleAllowed(unsigned long now)
{
    int recent = 0;
    for (int i = 0; i < toggleCount; i++)
    {
        if (now - toggleTimes[i] < TOGGLE_WINDOW_MS)
        {
            recent++;
        }
    }
    return recent < MAX_TOGGLES;
}

void recordToggle(unsigned long now)
{
    if (toggleCount < MAX_TOGGLES)
    {
        toggleTimes[toggleCount++] = now;
    }
    else
    {
        for (int i = 1; i < MAX_TOGGLES; i++)
        {
            toggleTimes[i - 1] = toggleTimes[i];
        }
        toggleTimes[MAX_TOGGLES - 1] = now;
    }
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    Serial.begin(9600);
}

void loop()
{
    int raw = analogRead(SENSOR_PIN);
    float tempC = raw * (5.0 / 1023.0) * 100.0;

    bool wantOn;
    if (tempC < FAULT_LOW_C || tempC > FAULT_HIGH_C)
    {
        wantOn = true;
    }
    else if (tempC >= FAN_ON_C)
    {
        wantOn = true;
    }
    else if (tempC <= FAN_OFF_C)
    {
        wantOn = false;
    }
    else
    {
        wantOn = fanOn;
    }

    if (wantOn == fanOn)
    {
        pendingCount = 0;
    }
    else
    {
        if (wantOn == pendingState)
        {
            pendingCount++;
        }
        else
        {
            pendingState = wantOn;
            pendingCount = 1;
        }

        if (pendingCount >= CONFIRM_SAMPLES)
        {
            unsigned long now = millis();
            if (toggleAllowed(now))
            {
                fanOn = wantOn;
                recordToggle(now);
            }
            pendingCount = 0;
        }
    }

    digitalWrite(FAN_PIN, fanOn ? HIGH : LOW);

    Serial.print("temp=");
    Serial.println(tempC);
    delay(100);
}
